import path from "node:path";

export function sanitizePath(input: string): string {
  const cleaned = path.normalize(input);
  if (cleaned.includes("..")) {
    throw new Error("traversal blocked");
  }
  return cleaned;
}

export const safe_join = (base: string, target: string): string => path.join(base, target);
